import 'dart:convert';

import 'package:flutter/services.dart';

import '../models/content.dart';

/// Source of lesson content. The app only depends on this interface, so switching the
/// prototype's bundled JSON to Firestore is a provider override, not a UI change.
abstract class ContentRepository {
  Future<Catalog> loadCatalog();
}

/// Reads the structured catalog bundled with the app (generated by tool/build_content.py).
class LocalContentRepository implements ContentRepository {
  final AssetBundle bundle;
  LocalContentRepository([AssetBundle? bundle]) : bundle = bundle ?? rootBundle;

  @override
  Future<Catalog> loadCatalog() async {
    final raw = await bundle.loadString('assets/content/catalog.json');
    return Catalog.fromJson(jsonDecode(raw) as Map<String, dynamic>);
  }
}
